  --success: #73b87e;
  --danger: #e06060;
}
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}
body {
  background: var(--bg);
  color: var(--text);
  font-family: "Inter", -apple-system, sans-serif;
  font-size: 13px;
  line-height: 1.5;
}
.header {
  border-bottom: 1px solid var(--border);
  padding: 24px 32px 20px;
}
.header h1 {
  font-size: 20px;
  font-weight: 600;
  color: var(--text-bright);
  margin-bottom: 4px;
}
.header-meta {
  font-size: 12px;
  color: var(--text-muted);
  display: flex;
  gap: 16px;
  align-items: center;
  margin-top: 8px;
}
.pill {
  display: inline-flex;
  padding: 1px 8px;
  border-radius: 10px;
  font-family: "IBM Plex Mono", monospace;
  font-size: 11px;
  font-weight: 500;
}
.pill.add {
  background: #73b87e22;
  color: var(--success);
}
.pill.del {
  background: #e0606022;
  color: var(--danger);
}
.pill.files {
  background: #7aa2f722;
  color: var(--accent);
}
.content {
  max-width: 900px;
  margin: 0 auto;
  padding: 24px 20px 60px;
}
.summary {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 16px 20px;
  margin-bottom: 28px;
  font-size: 13px;
  line-height: 1.6;
}
.summary strong {
  color: var(--text-bright);
}
.summary ul {
  margin-top: 8px;
  padding-left: 18px;
}
.summary li {
  margin-bottom: 4px;
}
.section-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-bright);
  margin: 28px 0 12px;
  padding-bottom: 6px;
  border-bottom: 1px solid var(--border);
}
.ic {
  font-family: "IBM Plex Mono", monospace;
  font-size: 11px;
  background: var(--surface-raised);
  padding: 1px 5px;
  border-radius: 3px;
  color: var(--accent);
}

.file-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 6px;
  margin-bottom: 12px;
}
.file-hdr {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 14px;
  background: var(--surface-raised);
  border-bottom: 1px solid var(--border);
  cursor: pointer;
  user-select: none;
  position: sticky;
  top: 0;
  z-index: 12;
  border-radius: 6px 6px 0 0;
}
.file-hdr:hover {
  background: #303030;
}
.file-hdr .fname {
  font-family: "IBM Plex Mono", monospace;
  font-size: 12px;
  color: var(--accent);
}
.file-hdr .fstats {
  display: flex;
  gap: 6px;
  align-items: center;
}
.file-hdr .chev {
  color: var(--text-muted);
  transition: transform 0.15s;
  font-size: 11px;
  margin-left: 10px;
}
.file-hdr .chev.open {
  transform: rotate(90deg);
}
.file-body {
  display: none;
}
.file-body.open {
  display: block;
}
.file-note {
  padding: 10px 14px;
  font-size: 13px;
  color: var(--text);
  line-height: 1.55;
  border-bottom: 1px solid var(--border);
  background: var(--surface);
  position: sticky;
  top: 35px;
  z-index: 11;
}
.file-note strong {
  color: var(--text-bright);
}
.file-note ul {
  margin-top: 6px;
  padding-left: 18px;
}
.file-note li {
  margin-bottom: 3px;
}

.bp-section {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 6px;
  margin-bottom: 8px;
}
.bp-hdr {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 14px;
  cursor: pointer;
  user-select: none;
  font-size: 12px;
  color: var(--text-muted);
}
.bp-hdr:hover {
  background: var(--surface-raised);
}
.bp-hdr .chev {
  color: var(--text-muted);
  transition: transform 0.15s;
  font-size: 11px;
}
.bp-hdr .chev.open {
  transform: rotate(90deg);
}
.bp-body {
  display: none;
  border-top: 1px solid var(--border);
}
.bp-body.open {
  display: block;
}
.bp-note {
  padding: 8px 14px;
  font-size: 12px;
  color: var(--text-muted);
  line-height: 1.5;
  border-bottom: 1px solid var(--border);
  background: var(--bg);
}

.diff-table {
  width: 100%;
  border-collapse: collapse;
  font-family: "IBM Plex Mono", monospace;
  font-size: 12px;
  line-height: 20px;
  table-layout: fixed;
  tab-size: 4;
}
.diff-table td {
  vertical-align: top;
  white-space: pre;
}
.diff-ln {
  width: 40px;
  min-width: 40px;
  max-width: 40px;
  text-align: right;
  padding: 0 6px 0 0;
  color: #555;
  background: var(--surface);
  user-select: none;
}
.diff-code {
  padding: 0 12px;
  color: var(--text);
  background: var(--bg);
  overflow-x: auto;
}
tr.diff-add .diff-ln {
  color: #5a8a5a;
  background: #1a2a1a;
}
tr.diff-add .diff-code {
  background: #1a2a1a;
  color: #c8e6c8;
}
tr.diff-del .diff-ln {
  color: #8a5a5a;
  background: #2a1a1a;
}
tr.diff-del .diff-code {
  background: #2a1a1a;
  color: #e6c8c8;
}
tr.diff-ctx .diff-ln {
  background: var(--surface);
}
tr.diff-ctx .diff-code {
  background: var(--bg);
  color: var(--text-muted);
}
tr.diff-hunk td {
  background: var(--surface-raised);
  color: var(--text-muted);
  font-size: 11px;
  padding: 3px 12px;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}
tr.diff-hunk .diff-ln {
  background: var(--surface-raised);
}
tr.diff-moved-del .diff-ln {
  color: #6a6a8a;
  background: #1a1a2a;
}
tr.diff-moved-del .diff-code {
  background: #1a1a2a;
  color: #a8a8d0;
}
tr.diff-moved-add .diff-ln {
  color: #6a6a8a;
  background: #1a1a2a;
}
tr.diff-moved-add .diff-code {
  background: #1a1a2a;
  color: #a8a8d0;
}
tr.diff-moved-del-edited .diff-ln {
  color: #7a6a8a;
  background: #221a2a;
}
tr.diff-moved-del-edited .diff-code {
  background: #221a2a;
  color: #c0a8d0;
}
tr.diff-moved-add-edited .diff-ln {
  color: #7a6a8a;
  background: #221a2a;
}
tr.diff-moved-add-edited .diff-code {
  background: #221a2a;
  color: #c0a8d0;
}

.verdict {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 16px 20px;
  margin-top: 28px;
}
.verdict h3 {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-bright);
  margin-bottom: 8px;
}
.verdict ul {
  padding-left: 18px;
}
.verdict li {
  font-size: 13px;
  margin-bottom: 6px;
  line-height: 1.5;
}
.verdict li strong {
  color: var(--text-bright);
}
